CREATE ROLE replicator WITH REPLICATION LOGIN CONNECTION LIMIT 3 PASSWORD '<from-secrets-store>';

-- a physical slot so the primary keeps WAL for this replica only
SELECT pg_create_physical_replication_slot('replica_dc2');

-- on the source
CREATE USER 'repl'@'10.30.2.12' IDENTIFIED BY '<from-secrets-store>' REQUIRE SSL;
GRANT REPLICATION SLAVE ON *.* TO 'repl'@'10.30.2.12';

-- on the replica
SET GLOBAL super_read_only = ON;
CHANGE REPLICATION SOURCE TO
  SOURCE_HOST='db-source.example.com',
  SOURCE_USER='repl',
  SOURCE_PASSWORD='<from-secrets-store>',
  SOURCE_SSL=1,
  SOURCE_SSL_CA='/etc/mysql/tls/ca.pem',
  SOURCE_SSL_VERIFY_SERVER_CERT=1;
START REPLICA;

